import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AS everyday-crime stories.
extension FollowUpCases {
    static let batchAS: [CaseTemplate] = [paintAgain, benefitsSecond, returnScamSecond, erResistAgain, perjuryDeposit, clinicBreakAgain, garageAgain, shotgunPawnAgain, mugThreat, lotFightAgain, pillSaleSecond, fireClaimBurn]

    static let paintAgain = SmallCases.make(
        key: "story.followup.paintAgain",
        category: .property,
        headlines: ["Another Overpass Painted, Same Lettering", "Defendant From Graffiti Case Linked by Style"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a city wall, causing damage of $800, on {DATE}.",
        ages: 18...25,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a retaining wall was painted in the same lettering. A camera caught a hooded figure. {DL} says the style is common.",
        state: [E(.video, 2, "Camera", "A hooded figure paints the wall."), E(.physical, 3, "Cans", "Matching cans in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Common Style", "{DL} says the style is common.")],
        role: "Public works supervisor",
        exam: [.direct("Please tell the jury what you do for the city.", "\"I'm a public works supervisor. I oversee the crew that maintains the streets, retaining walls and drainage in the north part of town, and I get called whenever something is damaged.\""), .direct("When did you first see the damage to the retaining wall?", "\"My crew found it at about six in the morning when they came in for a repair job. The whole wall face was covered in large lettering that had not been there the afternoon before.\""), .direct("What did the lettering look like?", "\"It was big block lettering with sharp points and a thick outline, in black and silver. I recognized the style right away because we cleaned up something very close to it before.\""), .direct("What did the camera on the wall show?", "\"It showed a person in a dark hooded sweatshirt working along the wall at about two in the morning. The person kept their head down, and you can see the cans in their hands.\""), .direct("What did it cost the city to deal with the wall?", "\"We had to bring in a pressure washer crew and then repaint the wall face, which came to about eight hundred dollars in labor and materials.\""), .direct("Were the cans from the car connected to the wall in any way?", "\"The deputies showed me photographs of the cans they found. They matched the black and silver colors that were used on the wall.\""), .cross("Can you see the person's face on the camera?", "\"No, I can't. The hood is up the whole time and the person never turns toward the lens.\""), .cross("Isn't it true that other people in town paint in a similar style?", "\"I've seen similar lettering on other walls, yes. I can't say how many people use it.\""), .cross("Did you personally see anyone painting that night?", "\"No. I only know what the camera shows and what my crew found when they arrived that morning.\""), .cross("Can you tell from the video what brand of can the person is holding?", "\"No, the video is too dark for that. The brand and colors came from the deputies' search and from the wall itself.\""), .cross("Spray cans are sold in every hardware store, aren't they?", "\"Yes, they are. I would not say the cans alone prove who was on that wall.\"")],
        theory: ("{D} painted the retaining wall again, in the same lettering that brought {D.him} to this court before.", "The lettering style is common in town, and the hooded figure on the camera cannot be identified as {DL}."),
        allocution: "\"I'm sorry for what happened to that wall. That lettering style is common around here, and I wasn't the hooded figure on the camera. I've been in this courtroom before, and I know that makes it easier to blame me. I'll help clean it up if the court asks.\"",
        truths: ("The lettering matched the pages of {DL}'s own sketchbook, and the cans in the car were the same brand and colors.", "Several other artists around town use the same lettering style, and the hooded figure's face never shows on the camera."),
        defendant: [.direct("Did you paint the retaining wall that night?", "\"No, I did not. I was not the person on that camera, and I never went near that wall.\""), .direct("Where were you at two in the morning?", "\"I was at home. I had worked a long shift and I was asleep well before midnight.\""), .direct("Tell us about your own art and where you practice it.", "\"I keep a sketchbook and I draw lettering in it. I practice at home on paper, and I've done a few permitted pieces where I had the owner's permission.\""), .direct("Why were spray cans in your car?", "\"I use them for a few small jobs and for painting the trim on a friend's fence. They had been rolling around in the trunk for weeks.\""), .direct("Why does the lettering on the wall look like your sketchbook?", "\"It's a very popular style, and a lot of people draw it that way. I learned it from videos and from other artists in town, the same as they did.\""), .direct("What did you do when deputies told you about the wall?", "\"I told them I didn't paint it and let them look through my car. I had nothing to hide.\""), .cross("You were in this court before over something similar, weren't you?", "\"Yes, I was, and I'm not proud of it. That was a different night, and it doesn't make me the person on this camera.\""), .cross("Your sketchbook has the same lettering, doesn't it?", "\"It has lettering in that style, yes. So do a lot of other people's sketchbooks around here.\""), .cross("You had spray cans that match the colors on the wall, didn't you?", "\"I had black and silver cans, yes. Those are the two colors every painter buys first.\""), .cross("Can anyone confirm you were home that night?", "\"My roommate was in the apartment, but we were both asleep. I can't prove it any better than that.\""), .cross("You can't tell us who the hooded figure is, can you?", "\"No, I can't. I wasn't there, so I don't know who it was.\"")],
        openings: ("A city retaining wall was covered in a large piece of lettering overnight, and a camera caught a hooded figure at work. Matching spray cans were later found in {D}'s car, and {DL} was in this court before over {PRIOR}. The State will show the video and the cans.", "The defense will present proof that this lettering style is common among local artists and that the camera never shows a face. Spray cans in a car are not rare, and {DL} was not the hooded figure on that wall."),
        closings: ("A hooded figure painted the wall at 2 a.m., and matching cans were in {D}'s car. This lettering is the same style that brought {DL} here in {PRIORDATE}. The evidence points to one person.", "A hooded figure with no visible face is not {D}. The style is common, and cans in a car prove nothing about who held them that night. The State has a suspicion built on a past case, not proof."),
        timeline: [(0, "2 a.m.: a hooded figure paints the retaining wall while a camera records."), (0, "6 a.m.: a public works crew finds the wall covered in lettering."), (1, "Deputies search {D}'s car and find matching spray cans.")],
        identified: "Camera",
        mood: .indifferent)

    static let benefitsSecond = SmallCases.make(
        key: "story.followup.benefitsSecond",
        category: .whiteCollar,
        headlines: ["Housing Assistance Questioned After Earlier Benefits Case", "Defendant Reports No Income Again"],
        law: "falsePretenses",
        spec: "Obtained $2,100 in housing assistance from {V}, a county agency, by false pretenses, on {DATE}.",
        ages: 22...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, an agency found {D} had again reported no income while working. {DL} says wages were paid in cash. The loss was put at $2,100.",
        state: [E(.document, 3, "Payroll", "Wages for six months."), E(.document, 3, "Application", "Signed no-income statement.")],
        defense: [E(.statement, 1, "Cash Wages", "{DL} says wages were cash and did not count.")],
        role: "Agency investigator",
        exam: [.direct("Please describe your work for the agency.", "\"I'm an investigator with the county agency. I review housing assistance files where the reported income doesn't match what employers or other records show.\""), .direct("How did this file come to your attention?", "\"A routine payroll match flagged it. {D} had reported no income on the application, but a payroll record showed wages going back six months.\""), .direct("What did the signed application say about income?", "\"It said in {D.his} own signature block that there was no income from any source. That statement is what the agency relied on in approving the assistance.\""), .direct("What did the payroll records show?", "\"They showed regular weekly wages for six months. The amounts were small but steady, and they added up to well beyond what a no-income statement would allow.\""), .direct("How much did the agency pay out during that period?", "\"We paid about $2,100 in housing assistance that we would have reduced or denied if the wages had been reported.\""), .direct("Did you explain the reporting rules to the applicant?", "\"The application form lists the reporting rules in plain language, and there is a signature line under them. I did not meet the applicant before the review.\""), .cross("Did you speak to the caseworker who handled this file?", "\"I did, briefly. The caseworker did not recall giving advice about cash wages and had no note of it in the file.\""), .cross("Does your agency tell applicants that some cash wages need not be reported?", "\"Our written policy says all income must be reported. I know that individual caseworkers sometimes explain it in their own words.\""), .cross("Were the wages large?", "\"No, they were small weekly amounts, and I would not call them large. The total over six months is what created the overpayment.\""), .cross("Did you find any hidden bank account or other concealed income?", "\"No. I found the payroll and nothing beyond it.\""), .cross("Has the agency recovered any of the $2,100?", "\"Not yet. Repayment would be handled by a separate process once this case is resolved.\"")],
        theory: ("{D} again reported no income to the housing agency while working steady jobs.", "{DL} was paid in cash and honestly believed that small cash wages did not have to be reported."),
        allocution: "\"I was paid in cash for a few jobs, and I didn't understand it had to be reported. I've been in this courtroom before, and I know I should have asked. I'll repay the agency, and I'll keep better records of everything I earn.\"",
        truths: ("The payroll shows steady wages for six months that {DL} never reported on the signed application.", "A caseworker told {DL} that cash wages under $200 did not need to be reported, and {DL} relied on that advice."),
        defendant: [.direct("Did you report your wages on the application?", "\"No, I did not. I wrote that I had no income, and I understood that to be true for the kind of pay I was getting.\""), .direct("How were you paid for your work?", "\"Mostly in cash, week to week, for painting jobs and moving furniture. There were no pay stubs, and nothing came out for taxes.\""), .direct("Why did you believe you didn't have to report it?", "\"My caseworker told me that small cash wages under two hundred dollars didn't have to go on the form. I took that to mean the jobs I was doing.\""), .direct("When did you first speak to the caseworker about this?", "\"At my first appointment, when I asked what counted as income. I walked out thinking I was fine to list zero.\""), .direct("What did you do with the money you earned?", "\"It went to rent, groceries and bus fare. I was behind and I was trying to keep from falling further behind.\""), .direct("Did you try to hide your work from the agency?", "\"No. I never told anyone to keep it quiet, and I'd have told them if anyone had asked me directly.\""), .cross("You signed the application, didn't you?", "\"Yes, I did. I signed it, and I should have read it more closely instead of relying on what I was told.\""), .cross("You had been in this court before over a similar matter, hadn't you?", "\"Yes, I had. That's why I'm so upset with myself for not asking for the advice in writing.\""), .cross("The payroll shows six months of wages, doesn't it?", "\"It does. Some weeks were more than two hundred, and I should have asked again when that happened.\""), .cross("Can you show anything in writing from the caseworker?", "\"No, I can't. It was something she said at the desk, and I didn't think to ask for it on paper.\""), .cross("You knew the form said all income must be reported, didn't you?", "\"The form says that, yes. I believed the caseworker's advice covered the small cash jobs I was doing.\"")],
        openings: ("A county agency paid $2,100 in housing assistance after {D} signed a statement reporting no income. A payroll record shows {D.he} was working for six months, and {DL} was in this court before over {PRIOR}. The State will show the application and the payroll side by side.", "The defense will present proof that {DL} was paid in cash for odd jobs and was told by a caseworker that small cash wages did not have to be reported. That is a misunderstanding of the rules, not a plan to deceive the agency."),
        closings: ("The signed application said no income. The payroll shows six months of wages, and {D} had been in this court before over {PRIOR}. Those two documents cannot both be true.", "{DL} relied on a caseworker's advice about small cash wages. A person who is told it need not be reported has not lied. The State has not proved an intent to deceive the agency."),
        timeline: [(-180, "{D} begins working steady jobs and is paid in cash."), (-150, "{D} signs an application stating no income."), (0, "The agency reviews payroll records and finds the wages.")],
        identified: "Payroll",
        mood: .sympathetic,
        genders: ["D": .female])

    static let returnScamSecond = SmallCases.make(
        key: "story.followup.returnScamSecond",
        category: .property,
        headlines: ["Return Fraud at Second Store", "Defendant From Return Case Flagged Again"],
        law: "larcenyMerchant",
        spec: "Obtained $310 in store credit from {V}, a retailer, by return fraud, on {DATE}.",
        ages: 20...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a different store flagged four returns by {D} with receipts that did not match. {DL} says they were gifts again.",
        state: [E(.document, 3, "Return Log", "Four mismatched returns."), E(.video, 2, "Counter Camera", "{D} at the counter.")],
        defense: [E(.statement, 1, "Gifts", "{DL} says they were gifts.")],
        role: "Store manager",
        exam: [.direct("Please tell the jury your position at the store.", "\"I'm the store manager. I supervise the registers, handle returns that need approval, and I review the return log every week for anything unusual.\""), .direct("What first drew your attention to these returns?", "\"The return log flagged four returns by the same customer in a single week. Each one used a receipt that didn't match the item being returned.\""), .direct("What did you find when you compared the receipts to the items?", "\"The receipts came from another retailer entirely. The item numbers and prices didn't line up with anything we sell.\""), .direct("What does the counter camera show?", "\"It shows {D} at the counter for each return, handing over the items and a receipt. I watched all four, and {D.he} was calm and patient each time.\""), .direct("How much store credit was issued?", "\"Altogether about $310 in store credit was loaded onto cards before the fourth return was caught.\""), .direct("How does a return normally work at your store?", "\"The customer brings the item and the receipt, the clerk scans the receipt, and the register confirms the item was sold by us. If the receipt doesn't scan, it goes to a manager.\""), .cross("Did {DL} ever tell a clerk the items were gifts?", "\"Yes, one clerk wrote that down. {DL} said they were gifts and that {D.he} was trying to return them.\""), .cross("Did any clerk question the receipts at the time?", "\"Not at the first two returns. The receipts looked ordinary, and it was only the weekly review that caught the mismatch.\""), .cross("Does your store accept gifts returned without a receipt?", "\"We do, but only for store credit at the lowest sale price. In these cases, the customer received the full amount.\""), .cross("Did {DL} act nervous or hide at the counter?", "\"No, {D.he} was relaxed and waited in line like anyone else. That was one of the things I noted.\""), .cross("Have you spoken to whoever gave {DL} the items?", "\"No, I have not. The deputies handled that, and I only know what was in the report.\"")],
        theory: ("{D} again returned items to a store with receipts that did not match, this time at a different retailer.", "The items were gifts from a friend, and {DL} returned them believing the receipts were valid."),
        allocution: "\"Those items were gifts from a friend, and I thought I could return them without a receipt matching. I've been in this courtroom before, and I know how it looks at a second store. I'll stop returning anything that isn't mine.\"",
        truths: ("The receipts were from another store, and four returns in a single week is a pattern the register logs caught.", "A friend confirmed giving {DL} four items along with their receipts, so the returns were an honest mistake."),
        defendant: [.direct("Did you return those four items to the store?", "\"Yes, I did. They were gifts, and I returned them for store credit because I didn't need them.\""), .direct("Who gave you the items?", "\"A friend who had bought several things for me and then packed the receipts into the same bags. I trusted that everything in the bag belonged together.\""), .direct("What did you think about the receipts?", "\"I thought they were the right ones. I didn't read them closely, and I didn't realize they were from a different store.\""), .direct("Why did you return four items in one week?", "\"I was clearing out a closet and I'd gotten more gifts than I could use. I brought them in as I had time.\""), .direct("What did you do with the store credit?", "\"I used it to buy school clothes for my kids and some groceries. I wasn't hiding it from anybody.\""), .direct("Did you speak with the clerks about the receipts?", "\"I told one clerk the items were gifts. I assumed that if there was a problem, the register would reject it.\""), .cross("You have been in this court before over a similar matter, haven't you?", "\"Yes, I have, and I know how that looks at a second store. This time I really believed the receipts were right.\""), .cross("Did you check the receipts before you handed them over?", "\"No. I should have, and I'll always check from now on.\""), .cross("Four returns in a week is a lot, isn't it?", "\"It is. I wasn't thinking about how it would add up to someone watching the log.\""), .cross("Your friend gave you the receipts, didn't they?", "\"Yes, they were in the bags with the items. My friend has told the deputies the same thing.\""), .cross("You received store credit for items you didn't buy, correct?", "\"That's true, I didn't buy them. I thought a gift was mine to return.\"")],
        openings: ("Over one week a store logged four returns by {D} in which the receipts did not match the items. The counter camera shows {D} at the register, and {DL} was in this court in {PRIORDATE} over {PRIOR}. The State will show the log and the video.", "The defense will present proof that these items were gifts from a friend, who handed over the items and the receipts together. {DL} returned them believing they were valid. A mismatched receipt is not fraud when a person trusts what a friend handed over."),
        closings: ("Four returns in one week, four receipts that did not match, and {D} at the counter every time. This is not an accident. It is the same behavior that brought {DL} here before.", "The items were gifts, and the receipts came with them. {D} brought them back believing they were good. A friend's mistake about a receipt is not a crime, and the State has not shown otherwise."),
        timeline: [(-7, "{D} makes the first return at the store counter."), (-4, "Two more returns in the same week, again with mismatched receipts."), (0, "The fourth return is flagged, and the manager pulls the log.")],
        identified: "Return Log",
        mood: .indifferent)

    static let erResistAgain = SmallCases.make(
        key: "story.followup.erResistAgain",
        category: .publicOrder,
        headlines: ["Deputy Struggles With Same Man at Clinic", "Defendant From Hospital Scuffle Cited Again"],
        law: "resisting",
        spec: "Resisted, delayed, and obstructed a public officer, on {DATE}.",
        ages: 20...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} refused to leave a clinic waiting room and pulled from a deputy's grasp. {DL} says {D.he} was waiting for results.",
        state: [E(.statement, 3, "Deputy", "{D} refused to leave."), E(.video, 2, "Clinic Camera", "{D} pulls away.")],
        defense: [E(.statement, 1, "Waiting", "{DL} says {D.he} was waiting for results.")],
        role: "Sheriff's deputy",
        exam: [.direct("Please state your job and your assignment that night.", "\"I'm a sheriff's deputy. That evening I was on patrol and got a call from the clinic staff about a person who wouldn't leave after closing.\""), .direct("What did the clinic staff tell you?", "\"They said the clinic had closed, everyone had gone home, and one person was still sitting in the waiting room and wouldn't leave when asked.\""), .direct("What did you see when you arrived?", "\"I found {D} sitting in a chair in the waiting room with a phone in hand. The lights were already half off and the front desk was empty.\""), .direct("What did you say to {D.him}?", "\"I told {D.him} that the clinic was closed and that {D.he} needed to leave. I said it twice, calmly, and explained that staff wanted to lock up.\""), .direct("How did {DL} respond?", "\"{D.He} said {D.he} was waiting for results and wasn't going anywhere. I asked a third time, and {D.he} stayed seated.\""), .direct("What happened when you took hold of {D.his} arm?", "\"I took {D.his} forearm to help {D.him} up, and {D.he} pulled away sharply. The clinic camera shows that moment.\""), .cross("Was the front door of the clinic locked when you arrived?", "\"The front door was still unlocked. I walked in through it.\""), .cross("Was there a sign saying the clinic was closed?", "\"There was a sign on the glass door with the hours. I did not see whether {DL} had read it.\""), .cross("Did {DL} threaten you or raise a fist?", "\"No. {D.He} pulled away and said something about waiting, and I did not see any threats.\""), .cross("Did you know why {DL} was waiting?", "\"Only what {D.he} told me. I didn't have a way to check it that night.\""), .cross("Did {DL} struggle for long?", "\"No. It was a few seconds, and {D.he} stopped once I stepped back.\"")],
        theory: ("{D} refused a deputy's order to leave a closed clinic and then pulled away when taken by the arm.", "{DL} was frightened and waiting for medical results, and pulled away out of fear rather than defiance."),
        allocution: "\"I was waiting at that clinic for my results, and I was frightened, and I pulled away when the deputy took my arm. I've been in this courtroom before, and I should have just stayed calm. I regret making a scene in front of the patients.\"",
        truths: ("The clinic was closed and a deputy gave {DL} a clear order to leave, and {D.he} pulled away on camera.", "The clinic's front door was still unlocked and {DL} was waiting for test results, so there was no clear sign that {D.he} had to leave."),
        defendant: [.direct("Why were you at the clinic that evening?", "\"I had been tested earlier and was told to wait for my results. I didn't want to leave without hearing what they said.\""), .direct("What were you feeling while you waited?", "\"Scared. I was alone in the room and I'd been waiting for an hour, and I kept thinking about what the test might show.\""), .direct("Did you know the clinic had closed?", "\"Not really. The lights were on, the front door was open, and nobody told me to go until the deputy arrived.\""), .direct("What did the deputy say to you?", "\"The deputy told me the clinic was closed and I had to go. I told {OFF.him} I was waiting for results and asked if I could stay a little longer.\""), .direct("Why did you pull away?", "\"When he took my arm I flinched. I was frightened and I didn't think, and I pulled away before I understood what was happening.\""), .direct("How did you feel about it afterward?", "\"Embarrassed. I never wanted to make a scene in front of anybody, and I know it looked bad on the camera.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and that's part of why I was so nervous around a uniform. I should have stayed calm.\""), .cross("The deputy told you three times to leave, didn't the deputy?", "\"{OFF.He} asked more than once, yes. I kept saying I was waiting, and I probably wasn't listening.\""), .cross("You didn't leave when asked, did you?", "\"No, I didn't. I thought a few more minutes wouldn't hurt anyone.\""), .cross("You pulled away from a deputy, didn't you?", "\"Yes. I did it without thinking, and I'm sorry that I did.\""), .cross("Nobody at the clinic told you the results would be ready that night, did they?", "\"No one said that. I was hoping, and I stayed on that hope.\"")],
        openings: ("A clinic had closed for the evening when {D} was still sitting in the waiting room. A deputy asked {D.him} to leave, {D} refused, and the clinic camera shows {D.him} pulling away when the deputy took {D.his} arm. {DL} had been in this court before, in {PRIORDATE}, over {PRIOR}.", "The defense will present proof that the front door was still unlocked and that {DL} was waiting for medical results. Frightened people sometimes pull away without meaning to defy anyone. The deputy and the video will show confusion, not obstruction."),
        closings: ("The clinic was closed, the deputy gave a lawful order to leave, and {D} stayed in the chair. When the deputy took {D.his} arm, {D.he} pulled away. That is delay and resistance.", "The door was unlocked and {D} was waiting for results. Fear made {D.him} pull away. The State has not shown a person who meant to obstruct anyone, only one who was scared and confused."),
        timeline: [(0, "The clinic closes for the evening and the staff lock the back office."), (0, "A deputy arrives and asks {D} to leave the waiting room."), (0, "{D} stays seated, then pulls away from the deputy's grasp on camera.")],
        identified: "Deputy",
        mood: .indifferent,
        genders: ["D": .male])

    static let perjuryDeposit = SmallCases.make(
        key: "story.followup.perjuryDeposit",
        category: .whiteCollar,
        headlines: ["Landlord Keeps Deposit Again After Judgment", "Defendant From Perjury Case Faces New Fraud Claim"],
        law: "falsePretenses",
        spec: "Obtained a $900 deposit from {V}, a tenant, by false pretenses, on {DATE}.",
        ages: 30...70,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} paid a deposit for an apartment {D} did not own. {DL} says the owner agreed to rent through {D.him}.",
        state: [E(.document, 3, "Lease", "A lease and a $900 deposit."), E(.document, 3, "Deed", "{D} does not own the apartment.")],
        defense: [E(.statement, 1, "Authority", "{DL} says the owner agreed.")],
        role: "Tenant",
        exam: [.direct("Please tell the jury how you came to meet {D}.", "\"I was looking for an apartment and found a listing online. {DL} answered, showed me the unit and told me {D.he} was handling the rental for the owner.\""), .direct("What happened at the showing?", "\"{DL} walked me through the apartment, said the owner had agreed to let {D.him} rent it, and handed me a lease to sign.\""), .direct("How much did you pay?", "\"I paid a $900 deposit by check. {DL} said it would be held until I moved in and that the apartment would be mine on the first of the month.\""), .direct("What did you learn when you tried to move in?", "\"The key didn't work. I found the real owner, who told me {DL} had no authority to rent the place and had never even met {D.him}.\""), .direct("What did the owner say about {DL}?", "\"The owner said no one had ever agreed to anything and that the owner didn't know who was collecting deposits in that name.\""), .direct("Have you gotten your deposit back?", "\"No. I've asked, and nothing has come back to me yet.\""), .cross("Did {DL} ever claim to own the apartment?", "\"No. {D.He} said {D.he} was handling the rental for the owner, which is what I believed.\""), .cross("Did you ask for anything in writing from the owner before paying?", "\"No, I did not. I should have, and I'll live with that.\""), .cross("Did {DL} pressure you to pay quickly?", "\"A little. {D.He} said other people were interested, but I don't think it was more than that.\""), .cross("Did {DL} give you a receipt for the deposit?", "\"Yes, there was a receipt with {D.his} signature, and I gave it to the deputies.\""), .cross("Did {DL} refuse to talk to you after you found the owner?", "\"No, {D.he} answered my call and said it was a misunderstanding. I did not push further.\"")],
        theory: ("{D} collected a $900 deposit for an apartment {D.he} did not own.", "The owner's brother authorized {D.him} to collect deposits, so {DL} believed {D.he} had the authority to rent."),
        allocution: "\"The owner agreed verbally to rent through me, and I took the deposit believing I had the authority. I've been in this courtroom before, and I know I should have gotten that in writing. I'll refund {V}'s deposit as soon as I can.\"",
        truths: ("The owner never met {DL} and never agreed to rent the apartment to anyone through {D.him}.", "The owner's brother told {DL} to collect deposits on his behalf, and {DL} believed that was real permission."),
        defendant: [.direct("Did you take the $900 deposit from {V}?", "\"Yes, I did. I took it believing I had permission to rent the apartment for the owner's family.\""), .direct("Who gave you that permission?", "\"The owner's brother. He told me to collect deposits for the unit while the owner was out of town, and I took his word for it.\""), .direct("Did you ever meet the owner?", "\"No, I never did. I dealt with the brother only, and I assumed the brother spoke for the owner.\""), .direct("What did you do with the deposit?", "\"I held it for a few days and then gave most of it to the brother. I kept a small amount for my time showing the unit.\""), .direct("Why did you sign the lease yourself?", "\"The brother handed me a lease form and told me to use it. I thought that was how it was done.\""), .direct("What did you intend when you collected the deposit?", "\"I meant for {V} to move in. I never wanted anyone to lose money, and I was trying to help the family fill the apartment.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have, and I know I should have asked for something in writing from the owner.\""), .cross("You knew you did not own the apartment, didn't you?", "\"I knew I didn't own it. I thought I was acting for the owner, and I said so to {V}.\""), .cross("You never got anything in writing, did you?", "\"No. It was all spoken, and I made a mistake not getting it on paper.\""), .cross("Where is the $900 now?", "\"Most of it went to the brother, and I spent a little on gas and a few days of bills. I'll repay what I can.\""), .cross("The real owner says no one was authorized, doesn't the owner?", "\"That's what the owner says, and I believe the owner. I was misled by the brother.\"")],
        openings: ("{V} signed a lease and paid a $900 deposit for an apartment and then learned that {D} did not own it. The deed shows the real owner, and {DL} was in this court in {PRIORDATE} over {PRIOR}. The State will show the lease, the deposit and the deed.", "The defense will present proof that the owner's brother told {DL} to collect deposits on his behalf. {DL} believed {D.he} had permission, and a misunderstanding about authority is not a plan to take someone's money."),
        closings: ("{V} paid $900 on a lease signed by {D}, who did not own the apartment. The deed and the real owner both say so. This is a taking of money by pretending to have authority.", "{DL} was told by the owner's brother to collect deposits. {D.He} believed that gave {D.him} authority. The State has not shown that {DL} knew the permission was false."),
        timeline: [(-14, "{V} signs the lease and pays the $900 deposit to {D}."), (-7, "{V} is told to wait for a move-in date."), (0, "{V} finds the real owner, who says no one had been authorized.")],
        identified: "Lease",
        mood: .wantsConviction)

    static let clinicBreakAgain = SmallCases.make(
        key: "story.followup.clinicBreakAgain",
        category: .property,
        headlines: ["Pharmacy Door Pried Again", "Defendant From Dental Break-In Seen at Pharmacy"],
        law: "breakingVehicle",
        spec: "Broke or entered a vehicle belonging to {V}, a pharmacist, with intent to commit larceny, on {DATE}.",
        ages: 20...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a pharmacist's car was entered and a bag of medication taken. A camera caught {D}. {DL} says {D.he} was passing through.",
        state: [E(.video, 3, "Camera", "{D} at the car."), E(.physical, 3, "Bag", "The bag in {D}'s trunk.", .search)],
        defense: [E(.statement, 1, "Passing", "{DL} says {D.he} was passing through.")],
        role: "Pharmacist",
        exam: [.direct("Please describe your work and why you were at the clinic.", "\"I'm a pharmacist. I fill prescriptions for the clinic's patients and deliver supplies, and I had parked in the clinic lot that morning.\""), .direct("What did you find when you returned to your car?", "\"The back window on the passenger side had been broken, and a bag with medication I was delivering was gone.\""), .direct("What was in the bag?", "\"It contained a number of prescription medications in labeled bottles that were headed to patients in the community.\""), .direct("What does the clinic camera show?", "\"It shows {D} walking up to my car and standing at the passenger side for several seconds before walking away toward the street.\""), .direct("How did deputies find the bag?", "\"They searched {D.his} car after identifying the plate on the camera. The bag was in the trunk with its labels intact.\""), .direct("How were the medications affected?", "\"Two of the bottles had been opened, and I couldn't give any of them out after that. The loss to the clinic was significant.\""), .cross("Does the camera show {DL} breaking the window?", "\"No. It shows {D.him} standing near the car, but the window itself is not in the frame at that moment.\""), .cross("Did you see anyone near your car before you went in?", "\"No. It was a quiet morning and the lot was empty when I parked.\""), .cross("Did you see the bag on the ground before you left it?", "\"No. I left it on the back seat, and I locked the car.\""), .cross("Is it possible a bag fell out when the window was broken?", "\"It's possible, but I can't say how it got from the car to the ground, if it did.\""), .cross("How long were you inside the clinic?", "\"About twenty minutes, and it was during that window that the car was entered.\"")],
        theory: ("{D} broke into a pharmacist's car and took a bag of medication, and the bag turned up in {D.his} trunk.", "{DL} was only passing through the lot and picked up a bag that was lying on the ground."),
        allocution: "\"I was passing through that lot, and I found a bag on the ground, and I picked it up. I never broke into anyone's car. I've been in this courtroom before, and I know how it looks on camera. I hope the court will listen.\"",
        truths: ("A pry bar was in {DL}'s trunk along with the bag, and the camera shows {D.him} at the pharmacist's car.", "The pry bar was a roofing tool {DL} used at work, and the bag was found on the ground, not taken from the car."),
        defendant: [.direct("Did you break into the pharmacist's car?", "\"No. I never touched that car, and I never broke a window.\""), .direct("What were you doing in the clinic lot that morning?", "\"I was passing through on my way to a job site. I cut across the lot to avoid a stoplight.\""), .direct("Where did you find the bag?", "\"On the ground by the passenger side of a car, next to some broken glass. I picked it up and was going to bring it inside.\""), .direct("Why did you put it in your trunk?", "\"I was running late, and I thought I'd drop it at the front desk on my way back. I should have gone in right then.\""), .direct("Why did you have a pry bar in your trunk?", "\"I'm a roofer. I use that bar every day to pull shingles, and it travels in the trunk with the rest of my tools.\""), .direct("What did you do when deputies stopped you?", "\"I told them where I found the bag and showed them the trunk. I didn't hide anything.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have, and that is why I know how a bag in my trunk looks. I'm telling the truth.\""), .cross("You picked up a bag that wasn't yours, didn't you?", "\"I did. I intended to return it, and I should have done it right then.\""), .cross("The camera shows you at the car for several seconds, doesn't it?", "\"It does. I was looking at the broken glass and the bag, trying to figure out what to do.\""), .cross("You never told the clinic about the bag, did you?", "\"No, I didn't. I meant to, and then I got pulled over before I could.\""), .cross("Why didn't you call someone about the broken window?", "\"I should have. I didn't think about it, and that was a mistake.\"")],
        openings: ("A pharmacist's car was entered in a clinic lot and a bag of medication was taken. A camera shows {D} at the car, and deputies found the bag in {D.his} trunk. {DL} has a history with this court from {PRIORDATE}, when the case was {PRIOR}.", "The defense will present proof that {DL} was passing through the lot and found a bag on the ground. A pry bar in a trunk is a roofing tool from {D.his} job, and picking up a dropped bag is not breaking into a car."),
        closings: ("The camera shows {D} at the pharmacist's car, and the missing bag was in {D.his} trunk with a pry bar. That is what a car break-in leaves behind.", "{D} was passing through a lot and picked up a bag lying on the ground. The pry bar is a roofing tool. The State has not shown that {DL} ever opened that car."),
        timeline: [(0, "The pharmacist parks at the clinic and goes inside."), (0, "The car is entered and a bag of medication is taken."), (0, "{D} drives away and deputies later find the bag in {D.his} trunk.")],
        identified: "Camera",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let garageAgain = SmallCases.make(
        key: "story.followup.garageAgain",
        category: .property,
        headlines: ["Another Garage Entered While Family Away", "Defendant From Burglary Case Seen on Camera"],
        law: "burglary2",
        spec: "Broke and entered the dwelling of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a family returned to find their garage entered and tools gone. A doorbell camera showed {D}. {DL} says the camera shows a lookalike.",
        state: [E(.video, 3, "Doorbell Camera", "A man carries tools."), E(.physical, 3, "Tools", "Tools in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Lookalike", "{DL} says it is a lookalike.")],
        role: "Homeowner",
        exam: [.direct("Please tell the jury what you found when you came home.", "\"We came home in the afternoon and found the garage side door open. A lot of the tools my husband and I use for work and projects were gone.\""), .direct("What kinds of tools were taken?", "\"A circular saw, a drill set, a socket kit and a few hand tools, all of which we had marked. In total they were worth several hundred dollars.\""), .direct("What did the doorbell camera show?", "\"It showed a man walking down the side of the house carrying a bag and a toolbox. He came back twice and then left in a car.\""), .direct("How did you know the tools were yours when deputies found them?", "\"Each tool has our last name scratched into the handle. My husband does that to everything because tools walk off at job sites.\""), .direct("Where did deputies find the tools?", "\"In the trunk and back seat of {D}'s car, a few days after the burglary.\""), .direct("How has this affected your household?", "\"We've had to replace tools we needed for work, and we put a lock on the garage. The whole family feels less safe.\""), .cross("Can you see the man's face on the doorbell camera?", "\"It's not a clear picture. I can see his general build and clothes, but the face is not sharp.\""), .cross("Did you see anyone at your garage before you went out that day?", "\"No. We left for the day and nobody was around.\""), .cross("Have you ever met {DL}?", "\"No, never. I only know the name from the deputies.\""), .cross("Do you know that a similar burglary took place nearby the next week?", "\"I've heard about it. I don't know the details or who was arrested for it.\""), .cross("Could another person have bought tools from a thief and had them in a car?", "\"I suppose it's possible, but the tools had our name on them, and it's hard for me to imagine that.\"")],
        theory: ("{D} broke into a family's garage and carried off tools that were found in {D.his} car.", "{DL} is not the man on the doorbell camera, and the tools were bought at a flea market."),
        allocution: "\"That camera shows someone who looks like me, but I wasn't there. I bought my tools at a flea market. I've been in this courtroom before, and I know it makes me an easy suspect. I'd never go into someone's garage.\"",
        truths: ("Tools etched with {V}'s name were found in {DL}'s car, and the doorbell camera shows a man carrying tools from the garage.", "A lookalike was arrested for a similar burglary the next week, and {DL} bought tools at a flea market."),
        defendant: [.direct("Were you at {V}'s garage on the day of the burglary?", "\"No. I've never been to that house, and I did not take anything from that garage.\""), .direct("Where did you get the tools in your car?", "\"I bought them from a table at a flea market. A man was selling a lot of used tools, and I bought a few for my own jobs.\""), .direct("Did you notice any name scratched on them?", "\"Some had markings, but a lot of used tools do. I didn't think anything about it.\""), .direct("How do you explain the man on the camera?", "\"It's a man who looks something like me, but it isn't me. The face isn't clear, and I wasn't there.\""), .direct("What were you doing that day?", "\"I was working a day job and was around coworkers most of the day. I can give you names.\""), .direct("What did you do when deputies asked about the tools?", "\"I told them where I bought them and what I paid. I let them look in the car and gave them everything.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have, and I know that makes me look like the easy answer. I didn't take these tools.\""), .cross("Can you name the man who sold you the tools?", "\"No, I can't. It was a cash sale at a table with no names.\""), .cross("You paid cash and have no receipt, don't you?", "\"That's right. I wish I'd gotten something in writing.\""), .cross("The tools had the family's name on them, didn't they?", "\"Some of them did. I didn't read them closely when I bought them.\""), .cross("The man on the camera looks like you, doesn't he?", "\"There's a resemblance, yes. A lot of people look alike in a blurry picture.\"")],
        openings: ("A family returned home to find their garage entered and their tools gone. A doorbell camera shows a man carrying tools away, and deputies later found tools with the family's name etched on them in {D}'s car. The court may recall {DL} from {PRIORDATE}, when {D.he} faced {PRIOR}.", "The defense will present proof that the camera image is blurry and shows a lookalike, and that {DL} bought tools at a flea market. A lookalike was arrested for a similar burglary the next week, and {DL} was not in that garage."),
        closings: ("The doorbell camera shows a man carrying tools away, and tools with {V}'s name etched on them were in {D}'s car. That connects {DL} to the garage.", "A blurry doorbell image shows a lookalike, and a similar burglary happened the next week with a different man arrested. Tools bought at a flea market are not proof that {D} was in that garage."),
        timeline: [(0, "The family leaves for the day and the garage is secured."), (0, "The garage is entered and tools are carried out."), (0, "The family returns, finds the loss, and checks the doorbell camera.")],
        identified: "Doorbell Camera",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        genders: ["D": .male])

    static let shotgunPawnAgain = SmallCases.make(
        key: "story.followup.shotgunPawnAgain",
        category: .property,
        headlines: ["Another Firearm Pawned After Truck Break-In", "Defendant From Shotgun Case Linked Again"],
        law: "possStolen",
        spec: "Possessed a rifle belonging to {V}, knowing it to be stolen, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a rifle stolen from a truck was pawned by {D}. The serial matched. {DL} says it was a trade.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID."), E(.document, 3, "Serial", "Matches records.")],
        defense: [E(.statement, 1, "Trade", "{DL} says it was a trade.")],
        role: "Gun owner",
        exam: [.direct("Please tell the jury about the rifle you owned.", "\"It was a bolt-action hunting rifle I had owned for about fifteen years. I kept the serial number written down in my gun log and in my phone.\""), .direct("When did you discover it was missing?", "\"On Monday morning I went to my truck and found the lock on the gun box broken and the rifle gone.\""), .direct("What did you do next?", "\"I called the sheriff's office, gave them the serial number and a full description, and filed a report the same day.\""), .direct("How did you learn where the rifle was?", "\"A deputy called me three days later and said a pawn shop had a rifle with a matching serial number.\""), .direct("Did you confirm it was yours?", "\"Yes. I went to the sheriff's office and identified it by the serial number, a scratch on the stock and a scope mount I had added.\""), .direct("Had you ever sold or traded that rifle to anyone?", "\"Never. It was mine, I hadn't given it to anybody, and nobody had permission to take it.\""), .cross("Did you know {D} before the theft?", "\"No, I'd never met {D.him}.\""), .cross("Do you know who actually broke into your truck?", "\"No. Nobody has been identified for the theft itself.\""), .cross("Did you see the pawn ticket yourself?", "\"Yes, the deputy showed me a copy. It had {DL}'s name and ID number on it.\""), .cross("Did the pawn shop have any trouble tracing the rifle?", "\"No. They kept the rifle and the records, and gave everything to the sheriff right away.\""), .cross("Is it unusual for a thief to use a real ID at a pawn shop?", "\"It's not what I'd expect, no. I can't explain it.\"")],
        theory: ("{D} pawned a rifle that had just been stolen from a truck, using {D.his} own identification.", "{DL} got the rifle in a trade and had no idea it was stolen."),
        allocution: "\"I got that rifle in a trade, and I didn't know it was stolen. I took it to the pawn shop under my own name. I've been in this courtroom before, and I know it looks like a pattern. I'll cooperate fully to get it back to its owner.\"",
        truths: ("The serial number matches the rifle stolen from the truck, and the pawn ticket carries {DL}'s ID.", "The man who traded {DL} the rifle sent a photo of the swap, so {DL} had no reason to suspect it was stolen."),
        defendant: [.direct("Did you steal the rifle from {V}'s truck?", "\"No. I've never been near that truck, and I didn't steal anything.\""), .direct("How did you come to have the rifle?", "\"I traded for it with a man I met at a gun show. I gave him a power tool set and some cash for it.\""), .direct("Why did you take it to the pawn shop?", "\"I needed money to cover rent that month, and a rifle is worth something. I took it in under my own name.\""), .direct("What identification did you show?", "\"My own driver's license. I signed the ticket and gave my real address and phone number.\""), .direct("Do you have anything showing the trade?", "\"A text with a photo of the rifle swap. The man sent it to me afterward, and I still have it on my phone.\""), .direct("When did you learn it was stolen?", "\"When deputies came to my house and told me the serial matched. I was shocked, and I told them everything.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have, and I know it looks like a pattern. I didn't know this rifle was stolen.\""), .cross("You can't name the man you traded with, can you?", "\"No, I only know his first name. He told me he was selling to make room in his safe.\""), .cross("You didn't check the serial number against any record, did you?", "\"No, I didn't. I wish I'd thought of it, and I'd do that now.\""), .cross("You got a rifle worth hundreds for a tool set, didn't you?", "\"It was a good deal, and I should have asked more questions. I thought I'd lucked out.\""), .cross("You pawned it three days after the theft, didn't you?", "\"I pawned it the same week I got it. I didn't know it was stolen, so I didn't think of the timing.\"")],
        openings: ("A rifle was stolen from a truck and three days later it was pawned under {D}'s own name. The serial number on the pawn ticket matches the owner's records, and {DL} was in this court in {PRIORDATE} over {PRIOR}.", "The defense will present proof that {DL} got the rifle in a trade and pawned it openly under {D.his} own ID. A person who knows a rifle is stolen does not usually hand over a driver's license at the counter."),
        closings: ("The rifle was stolen on Monday and pawned by {D} on Thursday. The serial number matches the owner's records, and the ticket has {DL}'s identification. That is knowing possession.", "{D} traded for the rifle, took it to a pawn shop and signed with a real ID. That is how an honest person acts, not someone who knows an item is stolen."),
        timeline: [(0, "The rifle is stolen from the owner's truck."), (3, "{D} pawns the rifle under {D.his} own ID."), (5, "Pawn records are matched to the owner's serial number.")],
        identified: "Pawn Ticket",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction)

    static let mugThreat = SmallCases.make(
        key: "story.followup.mugThreat",
        category: .publicOrder,
        headlines: ["Threat Made to Bar Patron After Mug Case", "Defendant From Bar Fight Case Cited for Threat"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, a patron, on {DATE}.",
        ages: 21...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} saw {V} at a store and said 'Next time it won't be a mug.' A clerk heard. {DL} says it was a joke.",
        state: [E(.statement, 3, "Clerk", "{D} said the threat."), E(.video, 2, "Store Camera", "{D} approaches {V}.")],
        defense: [E(.statement, 1, "Joke", "{DL} says it was a joke.")],
        role: "Patron",
        exam: [.direct("Please tell the jury how you know {D}.", "\"I know {D.him} from the earlier case. I was the person involved in what happened with the mug, and I ended up testifying in this court about it.\""), .direct("What happened in the store that day?", "\"I was picking up a few groceries when {DL} came up behind me and said, 'Next time it won't be a mug.' I felt my stomach drop.\""), .direct("How did you understand those words?", "\"I understood it as a threat. I was hit with a mug in the earlier incident, and I took it to mean that something worse could happen.\""), .direct("What was {D.his} tone and demeanor?", "\"{D.He} said it low and close, without a smile. I didn't hear anything that sounded like a joke.\""), .direct("Who else heard the statement?", "\"The clerk at the register heard it. The clerk looked up, and then called for a manager to stay near me.\""), .direct("What did you do after that?", "\"I left my cart and walked outside. I called the sheriff's office from the parking lot and reported what I'd heard.\""), .cross("Did {DL} touch you in the store?", "\"No. {D.He} stood near me and spoke, and nothing physical happened.\""), .cross("Did you see {DL} laugh when {D.he} said it?", "\"I didn't see a laugh, but I wasn't looking closely. I was frozen, and I turned away.\""), .cross("Did you notice whether {DL} was on the phone?", "\"I recall {D.him} holding a phone, but I didn't hear anyone on the line.\""), .cross("Had you been avoiding {DL} before that day?", "\"Yes, I'd been trying to keep out of the way. I did not expect to see {D.him} at that store.\""), .cross("Did {DL} follow you outside?", "\"No, {D.he} stayed in the store, and I don't know where {D.he} went after that.\"")],
        theory: ("{D} threatened {V} in a store, saying next time it would not be a mug.", "{DL} was joking after an awkward run-in and did not mean the words as a threat."),
        allocution: "\"I said that to {V} as a joke when we ran into each other, and I was nervous. I've been in this courtroom before, and I know how it sounded. I'll stay away from {V.him} and watch what I say.\"",
        truths: ("{DL} followed {V} into the store and then said the words directly to {V.him} where a clerk could hear.", "{DL} was telling a friend on the phone about a cartoon mug, and the words were a joke that {V} misheard."),
        defendant: [.direct("Did you say those words to {V} in the store?", "\"I did say something like that, but I said it as a joke. I was on the phone with a friend, and it was about a cartoon mug.\""), .direct("What were you talking about on the phone?", "\"My friend had sent me a picture of a cartoon mug with a funny saying on it. I was laughing about it while I walked.\""), .direct("Did you know {V} was in the store?", "\"Not when I walked in. I saw {V.him} near the register and I got nervous. I said the line the way I'd said it to my friend.\""), .direct("Why did you approach {V}?", "\"I was trying to be polite and clear the air about the past. I didn't know how to start, so I made a bad joke.\""), .direct("What did you mean by the words?", "\"I meant nothing by them. It was a quip I was repeating from the phone call, and I didn't realize how it would sound.\""), .direct("How did you feel when you learned {V} had called the sheriff?", "\"Awful. I never wanted to scare anybody, and I felt sick that it came across that way.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have, and I know that gave my words more weight. I should have kept my mouth shut.\""), .cross("You approached {V} on your own, didn't you?", "\"I did. I walked over because I wanted to say something, and I chose the wrong thing.\""), .cross("You knew about the earlier mug incident, didn't you?", "\"Yes, I knew. That's why I should have known not to joke about a mug.\""), .cross("Nobody heard your friend on the phone, did they?", "\"The clerk probably didn't. My friend can say what we talked about.\""), .cross("You didn't apologize to {V} that day, did you?", "\"No. I walked away, and I didn't think {V.he} was upset until later.\"")],
        openings: ("{V} and {D} had a run-in in the past, and {DL} was in this court in {PRIORDATE} over {PRIOR}. In a store {D} walked up to {V} and said 'Next time it won't be a mug.' A clerk heard it, and the store camera shows {D} approaching.", "The defense will present proof that {DL} was making a joke after an awkward meeting and meant no harm. Words said lightly, with a laugh, do not become a threat just because the listener was already on edge."),
        closings: ("{D} followed {V} into the store and said 'Next time it won't be a mug.' A clerk heard it and the camera shows {D} walk up. Given the history, those words were a threat.", "{D} was nervous and tried to make a joke, as people do. {V} took it hard because of the history. The State has not shown that {DL} meant to frighten anyone."),
        timeline: [(-10, "The earlier incident that led to {PRIOR}."), (0, "{D} follows {V} into the store."), (0, "{D} says the words, and a clerk reports it to deputies.")],
        identified: "Clerk",
        mood: .wantsConviction,
        impact: "I don't go out alone. {D.He} said next time it wouldn't be a mug, and a clerk heard it. I'd been hit before and I took it as a promise. I take someone with me to the store now. I'd like my errands to be ordinary again.",
        genders: ["V": .male])

    static let lotFightAgain = SmallCases.make(
        key: "story.followup.lotFightAgain",
        category: .violent,
        headlines: ["Punch in Parking Lot Again, Victim Says", "Defendant With Three Assault Priors Charged Again"],
        law: "simpleAssault",
        spec: "Assaulted {V}, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} punched {V} in a store parking lot after a dispute over a cart. {DL} says {V} swung first.",
        state: [E(.video, 3, "Store Camera", "{D} punches {V}."), E(.statement, 3, "Victim", "{V} says {D} swung first.")],
        defense: [E(.statement, 1, "Swung First", "{DL} says {V} swung first.")],
        role: "Victim",
        exam: [.direct("Please tell the jury what happened in the parking lot.", "\"I was returning a cart when {D} said I'd taken the one {D.he} wanted. We argued for a minute, and then {D.he} stepped toward me and punched me in the face.\""), .direct("How did the argument begin?", "\"It started over a shopping cart. I had it in my hands, and {DL} said it was {D.his}. I told {D.him} to take another one.\""), .direct("Where were your hands when {DL} struck you?", "\"At my sides, I think. I was holding the cart with one hand and I wasn't raising a fist.\""), .direct("What injuries did you have?", "\"My lip split, and I had a swollen cheek for a week. I went to urgent care to make sure nothing was broken.\""), .direct("What did the store camera record?", "\"It recorded {DL} stepping close and landing a punch. I watched it with the deputy and it matched what I remembered.\""), .direct("What did you do after you were hit?", "\"I backed away, got my phone and called the sheriff. A store clerk came out and stayed with me until deputies arrived.\""), .cross("Did you raise your hand at any point before {DL} punched you?", "\"I don't believe I did. I may have made a gesture, but I didn't swing.\""), .cross("Did you say anything harsh to {DL}?", "\"We both said things. I told {D.him} to find another cart, and I might have used some words I'm not proud of.\""), .cross("Can you be sure of every movement in that second?", "\"No. It happened fast, and my memory is of the punch.\""), .cross("Does the camera show the moment right before the punch?", "\"It shows us close together. The angle is from above and behind, so my arms are not clear.\""), .cross("Did you push the cart toward {DL}?", "\"I don't think so. I may have moved it, but I did not shove it into {D.him}.\"")],
        theory: ("{D} punched {V} in a store parking lot after an argument over a cart.", "{V} swung first, and {DL} hit back in the heat of the moment."),
        allocution: "\"I punched {V} in that parking lot, but {V.he} swung first over a shopping cart, and I reacted. I've been in this courtroom before, and I know how it sounds to say that. I should have walked to my car.\"",
        truths: ("The camera shows {DL} throw the first punch that landed, while {V} stood with arms down.", "{V} swung at {DL} first over the cart, and {DL} reacted without thinking."),
        defendant: [.direct("Did you punch {V} in the parking lot?", "\"Yes, I did, but {V} swung at me first. I only hit back after being swung at.\""), .direct("How did the argument begin?", "\"Over a shopping cart. {V} grabbed it out of my hands, and we got into it about who had it first.\""), .direct("What did {V} do before you punched?", "\"{V.He} threw a swing at me that I ducked part way. It caught my shoulder, and I reacted right away.\""), .direct("Why did you throw a punch?", "\"I wasn't thinking. I had been hit, and I hit back, which I know isn't a good excuse.\""), .direct("Where were you headed that day?", "\"I was picking up groceries before work. I had no plan to fight anyone and wasn't looking for trouble.\""), .direct("What did you do after the fight?", "\"I stepped back and said I was sorry. A clerk told me to stay, and I waited for the deputies.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have, and I've told myself since then to walk away. I didn't this time.\""), .cross("The camera doesn't show {V} swinging first, does it?", "\"The angle isn't great, but I know what happened. {V} swung before I did.\""), .cross("You could have walked away, couldn't you?", "\"I could have, and I wish I had. I was angry and I let it get to me.\""), .cross("{V} was injured and you weren't, correct?", "\"That's right. {V} had a split lip, and I felt bad seeing it.\""), .cross("You never told the clerk {V} hit first, did you?", "\"I may have said something at the time. I was upset and I don't recall exactly what.\"")],
        openings: ("A dispute over a shopping cart in a store parking lot ended with {D} punching {V}. The store camera shows the punch, and {V} will tell you {D} swung first. This is not {DL}'s first time here, since the {PRIORDATE} case was {PRIOR}.", "The defense will present proof that {V} swung first over the cart and that {DL} reacted. A person hit first does not stand still, and the question is who started it. The video, watched closely, supports {DL}."),
        closings: ("The camera shows a punch landing on {V} in a parking lot over a shopping cart. {V} had done nothing but argue. {D} chose to hit, and {DL} knew better from {PRIORDATE}.", "{V} swung first, and {D} hit back. That is not an assault the law punishes. The State asks you to ignore who started it, and that is the heart of this case."),
        timeline: [(0, "{D} and {V} argue over a shopping cart in the parking lot."), (0, "{V} and {D} exchange words, and a swing is thrown."), (0, "{D}'s punch lands, and a clerk calls the sheriff.")],
