        state: [E(.video, 3, "Recording", "{D} hands over four pills."), E(.physical, 3, "Marked Bills", "$80 in marked bills.", .search)],
        defense: [E(.statement, 1, "Change", "{DL} says {D.he} was making change.")],
        role: "Undercover officer",
        exam: [.direct("Please tell the jury about your work with the sheriff's office.", "\"I'm an undercover officer assigned to narcotics. I arrange small purchases to find out who is selling pills in our area.\""), .direct("How did you come to meet {D}?", "\"A confidential source arranged a meeting at a parking lot. The source told me {DL} could supply oxycodone pills.\""), .direct("What happened at the meeting?", "\"I asked for four pills, and {DL} handed them to me in a small bag. I handed over four twenty dollar bills.\""), .direct("What did the recording capture?", "\"It shows the hand-off, the money changing hands, and {D.his} voice quoting the price. The video is clear.\""), .direct("What did you find when {DL} was arrested?", "\"The marked bills were in {D.his} front pocket, along with a sock containing additional pills.\""), .direct("What were the pills tested to be?", "\"Oxycodone, a Schedule II controlled substance. The lab report confirmed it.\""), .cross("Did {DL} set the price?", "\"I believe {D.he} said $80, but I'd have to check the recording. I don't recall the exact words.\""), .cross("Did {DL} say whose pills they were?", "\"No. {D.He} did not say anything about an owner.\""), .cross("Did you speak to the friend who is said to have supplied them?", "\"No. The deputies have not located that person.\""), .cross("Did {DL} ever give back change?", "\"I handed over exactly $80, so no change was required.\""), .cross("Did you see {DL} take any other money?", "\"No, only the marked bills I gave {D.him}.\"")],
        theory: ("{D} sold four oxycodone pills to an undercover officer for $80.", "{DL} was only making change for a friend and never meant to sell anything."),
        allocution: "\"I was making change for a friend, and I never meant to sell anything. Those pills weren't mine. I've been in this courtroom before, and I know how that looks to an undercover officer. I'll accept the court's guidance.\"",
        truths: ("{DL} had pills in a sock again, and the marked bills were found on {D.him} after the buy.", "A friend admitted giving {DL} the pills to hand to a buyer, so {DL} was passing them along without a sale of {D.his} own."),
        defendant: [.direct("Did you sell pills to the officer?", "\"No. I handed over pills for a friend, and I thought I was just making change when money was handed to me.\""), .direct("Whose pills were they?", "\"My friend's. My friend asked me to meet a buyer because of running late and I lived near the lot.\""), .direct("Why did you have a sock of pills?", "\"My friend gave me a handful and told me to hold them until the buyer showed up. I put them in my sock to keep them safe.\""), .direct("What did you think when the officer gave you the bills?", "\"I thought it was the buyer paying my friend. I held the money for him and meant to give it right over.\""), .direct("Did you keep any of the money?", "\"No. It was still in my pocket when I was arrested, and I hadn't spent a dollar.\""), .direct("Have you ever sold pills before?", "\"No. I was in court before for a different matter, and I haven't sold anything.\""), .cross("You handed over four pills, didn't you?", "\"Yes, I did, for my friend. I understand that handing them over was the problem.\""), .cross("You took $80 from the officer, correct?", "\"I did, but I was holding it for my friend. I wasn't going to keep any of it.\""), .cross("You knew they were oxycodone, didn't you?", "\"I knew they were pills. I didn't ask what kind, and I should have.\""), .cross("Your friend isn't here today, is he?", "\"No. My friend is hard to find, and I wish I could produce that person.\""), .cross("You have been in this court before, haven't you?", "\"Yes, I have. I know it doesn't help me, but I'm telling the truth about this.\"")],
        openings: ("An undercover officer bought four oxycodone pills from {D} for $80 in marked bills. The recording shows the hand-off, and the marked bills were found on {D.him}. {DL} returns to this court after {PRIOR} in {PRIORDATE}.", "The defense will present proof that {DL} was making change for a friend and that the pills belonged to someone else. A friend who asked {DL} to hand them over does not make {DL} the seller."),
        closings: ("The recording shows pills going from {D}'s hand to the officer, and the marked bills were in {D.his} pocket. That is a sale of a Schedule II drug, and {DL} had been here before.", "A friend gave {D} the pills to hand to a buyer, and {D} made change. That is not selling. The State has to prove {DL} knew and meant to sell, and that proof is missing."),
